using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "MinimumSoulHeatAction", menuName = "Data/Battle/Battle Actions/Sothis/MinimumSoulHeat Action")]
public class MinimumSoulHeatAction : MinimumSoulHeatBasedAction
{
	[Header("Soul Heat")]
	[SerializeField]
	protected int minSoulHeatToUse;

	public int MinSoulHeatToUse => minSoulHeatToUse;

	public override bool CheckConditionToBeCasted(bool playerHand, DiceOwnerEnum diceOwnerEnum)
	{
		return GetSoulHeatAmountToUse(activateFeedback: true) >= minSoulHeatToUse;
	}
}
